CREATE TABLE public.crm_campaigns (
    id bigint NOT NULL,
    campaign_code character varying(50) NOT NULL,
    campaign_name character varying(200) NOT NULL,
    campaign_type character varying(30) NOT NULL,
    campaign_subtype character varying(50),
    planned_start_date date,
    planned_end_date date,
    actual_start_date date,
    actual_end_date date,
    budget numeric(18,2) DEFAULT 0,
    actual_cost numeric(18,2) DEFAULT 0,
    cost_currency character varying(10) DEFAULT 'CNY'::character varying,
    objectives text,
    target_participants integer,
    actual_participants integer DEFAULT 0,
    target_leads integer,
    actual_leads integer DEFAULT 0,
    target_conversions integer,
    actual_conversions integer DEFAULT 0,
    expected_roi numeric(10,2),
    actual_roi numeric(10,2),
    channels character varying(50)[],
    channel_ids bigint[],
    owner_id bigint,
    department_id bigint,
    team_members bigint[],
    related_campaign_id bigint,
    description text,
    content_plan jsonb DEFAULT '[]'::jsonb,
    landing_page_url character varying(500),
    status character varying(20) DEFAULT 'draft'::character varying,
    phase character varying(20),
    created_at timestamp(6) with time zone DEFAULT CURRENT_TIMESTAMP,
    updated_at timestamp(6) with time zone,
    created_by bigint,
    updated_by bigint,
    deleted_at timestamp(6) with time zone,
    version integer DEFAULT 1,
    is_deleted boolean DEFAULT false NOT NULL,
    deleted_time timestamp without time zone
);


