    contract_code character varying(50) NOT NULL,
    contract_name character varying(200) NOT NULL,
    customer_id integer NOT NULL,
    opportunity_id integer,
    quotation_id integer,
    contract_type character varying(50),
    start_date date,
    end_date date,
    currency character varying(10) DEFAULT 'CNY'::character varying,
    total_amount numeric(15,2) NOT NULL,
    paid_amount numeric(15,2) DEFAULT 0,
    unpaid_amount numeric(15,2) GENERATED ALWAYS AS ((total_amount - paid_amount)) STORED,
    status character varying(20) DEFAULT 'draft'::character varying,
    approval_status character varying(20) DEFAULT 'pending'::character varying,
    approved_by integer,
    approved_at timestamp(6) without time zone,
